std::vector<int> V1 {1, 2, 3};
std::vector<int> V2 {1, 2, 3};
std::vector<int> V3 {1, 4, 0};

// Equality (==, !=): Requires same size and matching elements
bool equal = (V1 == V2);    // true
bool notEqual = (V1 != V3); // true

// Ordering (<, >, <=, >=): Lexicographical comparison
// Compares elements pairwise until a difference is found
bool lessThan = (V1 < V3); // true (2 < 4 at index 1)

std::map<int, char> M1 {{1, 'a'}, {2, 'b'}};
std::map<int, char> M2 {{1, 'a'}, {2, 'c'}};

// Comparison defined for associated containers (map, set)
bool mapLess = (M1 < M2); // true (based on pair comparison)
